KG42.register("clusters-fe7dd0ed49792492f4b86bc6",{"id":"25-p2p_ancillary_bidding::v142-d-CL001","paper":"25-p2p_ancillary_bidding","label":"Community direct-trading participation of consumers and prosumers","record":{"cluster_id":"v142-d-CL001","label":"Community direct-trading participation of consumers and prosumers","market_meaning":"Demand-side consumers and prosumers can directly trade electrical energy with other participants and achieve local power balance through intra-community trading.","mechanism_ids":["v141-a-M01-p2p-cda"],"market_types":["LEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"The two chains jointly describe the participating entities and permitted activities in the same P2P mechanism; the identities of consumers and prosumers are retained separately, and specific admission review conditions are not derived from this.","assembly_status":"assembled","boundary_rationale":"Who may participate in direct trading and their permitted activities are taken as an independent rule boundary; specific order, matching, and price decisions are carried by other clusters.","chain_bindings":[{"chain_id":"v141-c-R007","ownership":"primary","role":"core","rationale":"Retain the permitted scope for consumer participation in direct trading."},{"chain_id":"v141-c-R008","ownership":"primary","role":"core","rationale":"Supplement the scope of prosumer participation, forming complementary entity coverage with consumers."}],"connections":[{"connection_id":"v142-d-CL001-CON01","from_chain_id":"v141-c-R007","to_chain_id":"v141-c-R008","kind":"complementary_scope","from_refs":["v141-c-R007::phi::v141-c-R007-C001"],"to_refs":["v141-c-R008::phi::v141-c-R008-C001"],"evidence_ids":["v141-b-g01-E01"],"rationale":"The same source explicitly lists the two types of participants and the direct trading activity in parallel; this is a complementarity of entity scope and does not mean that the two identities are the same or must participate simultaneously."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-CL001-G01","category":"unverified_source","description":"The B evidence on which the participation scope is based remains unverified; this cluster is only an assembly candidate permitted by the experiment.","chain_ids":["v141-c-R007","v141-c-R008"],"object_refs":["v141-c-R007::phi::v141-c-R007-C001","v141-c-R008::phi::v141-c-R008-C001"],"evidence_ids":["v141-b-g01-E01"],"proposal_ids":[],"required_work":"Follow-up manual verification of the source and participation scope is required; the current assembled status only indicates that the described qualitative rule has formed a candidate."}]},"rule_refs":["25-p2p_ancillary_bidding::v141-c-R007","25-p2p_ancillary_bidding::v141-c-R008"],"unresolved_rule_refs":[],"node_ids":["COMP-fc2134ec5ed3e3df","KG31-f7948395f3266e2b"]});
